import asyncio
from typing import Awaitable, Callable


async def run_tasks(
    tasks: list[Callable[[], Awaitable[None]]],
    max_concurrent: int,
) -> None:
    """Run async task factories with at most ``max_concurrent`` running at once.

    Tasks are started in order. If one task raises, the remaining tasks still
    run and the first exception is re-raised at the end. If ``run_tasks`` is
    cancelled (e.g. Ctrl+C under ``asyncio.run``), all in-flight tasks are
    cancelled and awaited so their cleanup code (``finally`` / ``except
    CancelledError``) runs to completion; tasks that never started are skipped.
    """
    if max_concurrent < 1:
        raise ValueError("max_concurrent must be >= 1")

    tasks = list(tasks)
    if not tasks:
        return

    it = iter(tasks)
    errors: list[BaseException] = []

    async def worker() -> None:
        for factory in it:
            try:
                await factory()
            except asyncio.CancelledError:
                raise
            except Exception as e:
                errors.append(e)

    workers = [
        asyncio.create_task(worker())
        for _ in range(min(max_concurrent, len(tasks)))
    ]

    try:
        await asyncio.gather(*workers)
    except BaseException:
        # Cancel in-flight tasks and wait for their cleanup to finish, even if
        # we receive further cancellations (e.g. repeated Ctrl+C) meanwhile.
        for w in workers:
            w.cancel()
        pending = set(workers)
        while pending:
            try:
                _, pending = await asyncio.wait(pending)
            except asyncio.CancelledError:
                continue
        for w in workers:
            if not w.cancelled():
                w.exception()  # mark retrieved to avoid "never retrieved" warnings
        raise

    if errors:
        raise errors[0]

